const fallbackProducts=[
{id:'p1',brand:'VVIP Edit',name:'Signature Top Handle Bag',category:'Bags',price:12800,status:'available',image:'assets/product-1.jpg',badge:'NEW ARRIVAL'},
{id:'p2',brand:'Swiss Timepieces',name:'Two-Tone Professional Watch',category:'Watches',price:42900,status:'available',image:'assets/product-2.jpg',badge:'COLLECTOR\'S PIECE'},
{id:'p3',brand:'Italian House',name:'Monogram Drawstring Boots',category:'Shoes',price:3900,status:'available',image:'assets/product-3.jpg',badge:'JUST IN'},
{id:'p4',brand:'Swiss Timepieces',name:'Diamond Dial Classic Watch',category:'Watches',price:28500,status:'available',image:'assets/product-4.jpg',badge:'CERTIFIED'},
{id:'p5',brand:'Paris Edit',name:'Vintage Drawstring Shoulder Bag',category:'Bags',price:6900,status:'available',image:'assets/product-5.jpg',badge:'VINTAGE'},
{id:'p6',brand:'VVIP Edit',name:'Emerald Evening Bag',category:'Bags',price:5200,status:'sold',image:'assets/hero.png',badge:'SOLD'},
{id:'p7',brand:'Fine Jewellery',name:'Gold Statement Bracelet',category:'Accessories',price:2600,status:'available',image:'assets/product-2.jpg',badge:'LIMITED'},
{id:'p8',brand:'Italian House',name:'Structured City Tote',category:'Bags',price:8600,status:'available',image:'assets/product-1.jpg',badge:'CURATED'}
];
let products=[],activeFilter='All',query='',cart=[],wishes=new Set(),expanded=false;
const $=s=>document.querySelector(s),money=n=>`MYR ${Number(n).toLocaleString('en-MY')}.00`,displayPrice=p=>p.category==='Bags'?'DM FOR PRICE · 私讯询价':money(p.price);
async function loadProducts(){const c=window.VVIP_CONFIG||{};if(c.supabaseUrl&&c.supabaseAnonKey){try{const r=await fetch(`${c.supabaseUrl}/rest/v1/products?select=*&order=sort_order`,{headers:{apikey:c.supabaseAnonKey,Authorization:`Bearer ${c.supabaseAnonKey}`}});if(r.ok)products=await r.json()}catch(e){console.warn('Catalog fallback in use')}}if(!products.length)products=fallbackProducts;renderProducts()}
function visible(){let v=products.filter(p=>(activeFilter==='All'||p.category===activeFilter)&&(`${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(query)));return expanded?v:v.slice(0,8)}
function renderProducts(){const v=visible();$('#productGrid').innerHTML=v.map(p=>`<article class="product-card ${p.status==='sold'?'sold':''}"><div class="product-media"><img src="${p.image_url||p.image}" alt="${p.name}"><span class="badge">${p.badge||'CURATED'}</span><button class="heart ${wishes.has(p.id)?'on':''}" data-wish="${p.id}" aria-label="Add ${p.name} to wishlist">${wishes.has(p.id)?'♥':'♡'}</button><button class="quick-add" data-add="${p.id}">${p.status==='sold'?'ENQUIRE ABOUT THIS PIECE':p.category==='Bags'?'ENQUIRE ON WHATSAPP':'ADD TO BAG'}</button></div><div class="product-info"><p class="product-brand">${p.brand}</p><h3>${p.name}</h3><span class="price">${p.status==='sold'?'SOLD · ENQUIRE':displayPrice(p)}</span></div></article>`).join('');$('#productStatus').textContent=`Showing ${v.length} of ${products.length} pieces`;$('#viewAllButton').textContent=expanded?'SHOW LESS':'VIEW ALL PIECES'}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),1800)}
function renderCart(){$('#cartCount').textContent=cart.length;$('#cartItems').innerHTML=cart.length?cart.map(p=>`<div class="cart-line"><img src="${p.image_url||p.image}" alt=""><div><h4>${p.name}</h4><p>${p.brand}</p><b>${money(p.price)}</b></div><button data-remove="${p.id}" aria-label="Remove">×</button></div>`).join(''):'<p class="cart-empty">Your shopping bag is ready for something exceptional.</p>';$('#cartTotal').textContent=money(cart.reduce((s,p)=>s+Number(p.price),0));const msg=cart.length?`Hello VVIP Paris Milan Global, I am interested in: ${cart.map(p=>p.name).join(', ')}.`:'Hello VVIP Paris Milan Global, I would like to enquire about your collection.';$('#whatsappCheckout').href=`https://wa.me/60143444311?text=${encodeURIComponent(msg)}`}
function openCart(){renderCart();$('#cartDrawer').classList.add('open');$('#cartDrawer').setAttribute('aria-hidden','false');$('#scrim').classList.add('show')}
function closeCart(){$('#cartDrawer').classList.remove('open');$('#cartDrawer').setAttribute('aria-hidden','true');$('#scrim').classList.remove('show')}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]'),wish=e.target.closest('[data-wish]'),rem=e.target.closest('[data-remove]'),filter=e.target.closest('[data-filter]');if(add){const p=products.find(x=>x.id===add.dataset.add);if(p.status==='sold'||p.category==='Bags'){window.open(`https://wa.me/60143444311?text=${encodeURIComponent('Hello VVIP Paris Milan Global, I would like to enquire about '+p.name+'.')}`,'_blank')}else{cart.push(p);renderCart();toast(`${p.name} added to your bag`)}}if(wish){wishes.has(wish.dataset.wish)?wishes.delete(wish.dataset.wish):wishes.add(wish.dataset.wish);$('#wishCount').textContent=wishes.size;renderProducts()}if(rem){cart=cart.filter(p=>p.id!==rem.dataset.remove);renderCart()}if(filter){activeFilter=filter.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===filter));renderProducts()}});
$('#searchInput').addEventListener('input',e=>{query=e.target.value.toLowerCase().trim();renderProducts()});$('#cartButton').onclick=openCart;$('#closeCart').onclick=closeCart;$('#scrim').onclick=closeCart;$('#viewAllButton').onclick=()=>{expanded=!expanded;renderProducts()};document.querySelectorAll('[data-filter-link]').forEach(a=>a.onclick=()=>{activeFilter=a.dataset.filterLink;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===activeFilter));renderProducts()});
const dialog=$('#valuationDialog');$('#valuationButton').onclick=()=>dialog.showModal();$('#closeValuation').onclick=()=>dialog.close();$('#valuationForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const c=window.VVIP_CONFIG||{};let ok=true;if(c.supabaseUrl&&c.supabaseAnonKey){try{const r=await fetch(`${c.supabaseUrl}/rest/v1/valuation_requests`,{method:'POST',headers:{apikey:c.supabaseAnonKey,Authorization:`Bearer ${c.supabaseAnonKey}`,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(data)});ok=r.ok}catch(err){ok=false}}$('#formMessage').textContent=ok?'Thank you. Our team will contact you shortly.':'We could not save this request. Please call 014-3444311.';if(ok)e.target.reset()};
const heroVideo=$('.hero-video'),soundToggle=$('#soundToggle');if(heroVideo&&soundToggle)soundToggle.onclick=()=>{heroVideo.muted=!heroVideo.muted;soundToggle.textContent=heroVideo.muted?'SOUND OFF':'SOUND ON';soundToggle.setAttribute('aria-label',heroVideo.muted?'Turn showcase sound on':'Mute showcase')};
loadProducts();renderCart();
